const startTeamDeletion = `-- name: StartTeamDeletion :one
UPDATE workspaces
SET deletion_state = 'deleting', deletion_error = '', deletion_step = 'projects', deletion_started_at = now(),
    deletion_forgotten = '{}', deletion_keep_dns = $1::boolean
WHERE id = $2 AND deletion_state <> 'deleting'
RETURNING id, name, created_at, slug, created_by, require_two_factor, deletion_state, deletion_error, deletion_step, deletion_started_at, deletion_forgotten, deletion_keep_dns
`

type StartTeamDeletionParams struct {
	KeepDns bool      `json:"keepDns"`
	ID      uuid.UUID `json:"id"`
}

// Marks the team as being deleted and clears the last failure. keep_dns is the
// choice made with the request; forgotten starts over with every run.
func (q *Queries) StartTeamDeletion(ctx context.Context, arg StartTeamDeletionParams) (Workspace, error) {
	row := q.db.QueryRow(ctx, startTeamDeletion, arg.KeepDns, arg.ID)
	var i Workspace
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.CreatedAt,
		&i.Slug,
		&i.CreatedBy,
		&i.RequireTwoFactor,
		&i.DeletionState,
		&i.DeletionError,
		&i.DeletionStep,
		&i.DeletionStartedAt,
		&i.DeletionForgotten,
		&i.DeletionKeepDns,
	)
	return i, err
}

